function rotateGrid(grid) {
  const n = grid.length
  for (let r = 0; r < n; r++) {
    for (let c = r + 1; c < n; c++) {
      const t = grid[r][c]
      grid[r][c] = grid[c][r]
      grid[c][r] = t
    }
  }
  for (const row of grid) row.reverse()
  return grid
}

